-- Giải mã payload base64 (đã kiểm: nhanh hơn và nhỏ hơn escape thập phân 62%)
local __B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local __LUT = table.create(256)
for __i = 1, 64 do __LUT[string.byte(__B64, __i)] = __i - 1 end
local function __b64decode(s, want)
    while #s % 4 ~= 0 do s = s .. "A" end
    local n4 = #s // 4
    local out = table.create(n4 * 3)
    local n, i = 0, 1
    for _ = 1, n4 do
        local a, b, c, d = string.byte(s, i, i + 3)
        local v = __LUT[a] * 262144 + __LUT[b] * 4096 + __LUT[c] * 64 + __LUT[d]
        n = n + 1
        out[n] = string.char(math.floor(v / 65536) % 256, math.floor(v / 256) % 256, v % 256)
        i = i + 4
    end
    local r = table.concat(out)
    if want and #r > want then r = string.sub(r, 1, want) end
    return r
end
local __ENGINE = "kaitun"
getgenv().KaitunEngineName = __ENGINE

local function __log(msg)
    local f = getgenv().KaitunLog
    if type(f) == "function" then pcall(f, msg) end
end

local __engine_thread
getgenv().KaitunStop = function()
    if __engine_thread then
        pcall(task.cancel, __engine_thread)
        __engine_thread = nil
        __log("engine đã bị dừng")
        return true
    end
    return false
end

local function __run_engine()
    local e = ENG[__ENGINE]
    if not e then return false, "unknown engine" end
    __log("nạp engine " .. __ENGINE)
    local ok, entry = pcall(e.chunk, buffer.fromstring(__b64decode(e.b64, e.len)))
    if ok and type(entry) == "function" then
        __log("chunk() -> function, bắt đầu chạy")
        local rok, err = pcall(entry)
        if not rok then
            __log("engine dừng: " .. tostring(err))
            warn("[kaitun/" .. __ENGINE .. "] " .. tostring(err))
        end
        return rok, err
    end
    __log("nạp thất bại: " .. tostring(entry))
    warn("[kaitun/" .. __ENGINE .. "] load failed: " .. tostring(entry))
    return false, entry
end-- Chạy engine trong MỘT thread được theo dõi. Nạp lại phải huỷ engine cũ trước,
-- nếu không sẽ có 2 engine chạy song song và nút "Dừng engine" mất tác dụng
-- (vì nó chỉ huỷ được thread mà nó biết).
local function __start_engine()
    if __engine_thread then
        pcall(task.cancel, __engine_thread)
        __engine_thread = nil
        __log("huỷ engine cũ trước khi nạp lại")
    end
    __engine_thread = task.spawn(function()
        local ok, err = __run_engine()
        __engine_thread = nil
        local u = getgenv().KaitunUI
        if u and u.StatusLabel then
            u.StatusLabel.Text = ok and (" Status : " .. __ENGINE .. " đã dừng")
                or (" Status : Engine lỗi — " .. tostring(err):sub(1, 40))
        end
    end)
    return true
end
getgenv().KaitunReload = __start_engine

