-- nếu không mỗi lần reload lại chồng thêm handler (InputChanged bắn mỗi lần
-- chuột di -> càng reload càng nặng).
do
    local old = getgenv().KaitunMenuConns
    if type(old) == "table" then
        for _, c in ipairs(old) do
            pcall(function() if c and c.Disconnect then c:Disconnect() end end)
        end
    end
    getgenv().KaitunMenuConns = {}
end
local function svcConnect(sig, fn)
    local c = sig:Connect(fn)
    local list = getgenv().KaitunMenuConns
    if type(list) == "table" and c then table.insert(list, c) end
    return c
end
