-- làm sạch bảng nạp từ file: chỉ giữ phần tử cùng kiểu với mẫu
local function sanitizeTable(loaded, sample)
    if type(loaded) ~= "table" or type(sample) ~= "table" then return sample end
    -- mẫu rỗng thì không có hình dạng để kiểm -> giữ nguyên những gì đã lưu
    local nSample = 0
    for _ in pairs(sample) do nSample = nSample + 1 end
    if nSample == 0 then return loaded end
    local out = {}
    local isArr = true
    for k in pairs(sample) do if type(k) ~= "number" then isArr = false break end end
    if isArr then
        -- mảng (Sword, Gun): chỉ giữ phần tử là chuỗi
        local nLoaded = 0
        for _ in pairs(loaded) do nLoaded = nLoaded + 1 end
        local n = 0
        for _, v in ipairs(loaded) do
            if type(v) == "string" then n = n + 1; out[n] = v end
        end
        -- rỗng mà file cũng rỗng => người dùng CỐ Ý tắt hết, giữ rỗng.
        -- rỗng vì mọi phần tử sai kiểu => mới lui về mặc định.
        if n == 0 then
            if nLoaded == 0 then return {} end
            return sample
        end
        return out
    end
    -- bảng khoá-chuỗi: giữ theo kiểu của mẫu, khoá lạ thì giữ nguyên
    for k, sv in pairs(sample) do
        local lv = loaded[k]
        if type(lv) == type(sv) then out[k] = lv else out[k] = sv end
    end
    for k, lv in pairs(loaded) do
        if out[k] == nil then out[k] = lv end
    end
    return out
end

local function kLogBad(k, gotType, wantType)
    if type(getgenv().KaitunLog) == "function" then
        pcall(getgenv().KaitunLog, string.format(
            "config: bỏ qua %q (kiểu %s, cần %s)", tostring(k), gotType, wantType))
    end
end

-- SAVEFILE + nạp config NGAY, trước khi dựng cửa sổ
local SAVEFILE = "KaitunConfig.lua"
local function loadConfig()
    if type(readfile) ~= "function" or type(isfile) ~= "function" then return false end
    local ok = pcall(function()
        if not isfile(SAVEFILE) then return end
        local loader = loadstring or load
        if type(loader) ~= "function" then return end
        local data = readfile(SAVEFILE)
        -- config hợp lệ chỉ vài KB; file lớn bất thường thì không nạp (tránh treo)
        if type(data) ~= "string" or #data > 262144 then return end
        local fn = loader("return "..data)
        -- AN NINH: config là dữ liệu, không phải mã. File config thường được
        -- chia sẻ qua lại, nên nếu nạp bằng môi trường toàn cục thì một file
        -- độc hại có thể gọi writefile/os/game... Chạy nó trong môi trường RỖNG
        -- thì nó chỉ dựng được bảng, không gọi được gì.
        if fn and type(setfenv) == "function" then
            local ok_env = pcall(setfenv, fn, {})
            if not ok_env then fn = nil end
        elseif fn then
            fn = nil          -- không sandbox được thì thà không nạp
        end
        if fn then
            local t = fn()
            if type(t) == "table" then
                -- chỉ nhận giá trị CÙNG KIỂU với mặc định; config sửa tay sai kiểu
                -- (chuỗi thay vì số, số thay vì bảng...) sẽ bị bỏ qua thay vì làm hỏng menu
                local defaults = defaultConfigs()
                for k, v in pairs(t) do
                    local d = defaults[k]
                    if d == nil then
                        Configs[k] = v
                    elseif type(v) == type(d) then
                        if type(d) == "table" then
                            Configs[k] = sanitizeTable(v, d)
                        else
                            Configs[k] = v
                        end
                    elseif kLogBad then
                        kLogBad(k, type(v), type(d))
                    end
                end
            end
        end
    end)
    return ok
end

loadConfig()

-- ---------- helpers ----------
local function new(class, props, parent)
    local o = Instance.new(class)
    for k, v in pairs(props or {}) do o[k] = v end
    if parent then o.Parent = parent end
    return o
end

local function corner(parent, r)
    new("UICorner", { CornerRadius = UDim.new(0, r or 6) }, parent)
end

local function stroke(parent, col, thick)
    new("UIStroke", { Color = col or C.accent, Thickness = thick or 1, Transparency = 0.55 }, parent)
end

local function label(parent, text, size, col, pos, anchor)
    return new("TextLabel", {
        BackgroundTransparency = 1,
        Size = size,
        Position = pos or UDim2.fromOffset(0, 0),
        AnchorPoint = anchor or Vector2.zero,
        Font = Enum.Font.GothamMedium,
        TextSize = 14,
        TextColor3 = col or C.text,
        TextXAlignment = Enum.TextXAlignment.Left,
        Text = text,
    }, parent)
end

local function button(parent, text, size, pos, col)
    local b = new("TextButton", {
        Size = size,
        Position = pos,
        BackgroundColor3 = col or C.row,
        AutoButtonColor = true,
        Font = Enum.Font.GothamBold,
        TextSize = 13,
        TextColor3 = C.text,
        Text = text,
        BorderSizePixel = 0,
    }, parent)
    corner(b, 6)
    return b
end

-- ---------- root gui ----------
local function parentGui()
    local ok, hui = pcall(function() return gethui and gethui() end)
    if ok and hui then return hui end
    local ok2, cg = pcall(function() return game:GetService("CoreGui") end)
    if ok2 and cg then return cg end
    return player:WaitForChild("PlayerGui")
end

