-- đếm được cả mảng (Configs.Sword = {"A","B"}) lẫn map (Configs.Quest = {A=true})
local function countOn(t)
    local n = 0
    if type(t) == "table" then
        for k, v in pairs(t) do
            if type(k) == "number" then n = n + 1
            elseif v == true then n = n + 1 end
        end
    end
    return n
end

local function refreshCounts()
    local swordOn = countOn(Configs.Sword)
    local gunOn = countOn(Configs.Gun)
    local questOn = countOn(Configs.Quest)
    if tabButtons.Sword then tabButtons.Sword.Text = "Sword " .. swordOn .. "/" .. #Configs.Sword end
    if tabButtons.Gun then tabButtons.Gun.Text = "Gun " .. gunOn .. "/" .. #Configs.Gun end
    if tabButtons.Quest then tabButtons.Quest.Text = "Quest " .. questOn .. "/" .. #questNames end
    getgenv().KaitunCounts = { Sword = swordOn, Gun = gunOn, Quest = questOn }
end

-- ---------- log console ----------
local LOGCAP = 200
local LOGLINES = {}
local logPage = pages.Log
logPage.ScrollBarThickness = 4

local function klog(msg)
    local line = string.format("[%02d:%02d:%02d] %s",
        math.floor(tick() / 3600) % 24,
        math.floor(tick() / 60) % 60,
        math.floor(tick()) % 60,
        tostring(msg))
    LOGLINES[#LOGLINES + 1] = line:gsub("[\r\n]", " ")
    if #LOGLINES > LOGCAP then table.remove(LOGLINES, 1) end
    for _, ch in ipairs(logPage:GetChildren()) do
        if ch:IsA("TextLabel") then ch:Destroy() end
    end
    for i, l in ipairs(LOGLINES) do
        local tl = new("TextLabel", {
            Size = UDim2.new(1, -8, 0, 16),
            Position = UDim2.fromOffset(4, (i - 1) * 16),
            BackgroundTransparency = 1,
            Font = Enum.Font.Code,
            TextSize = 11,
            TextColor3 = C.sub,
            TextXAlignment = Enum.TextXAlignment.Left,
            Text = l,
            LayoutOrder = i,
        }, logPage)
    end
    logPage.CanvasSize = UDim2.fromOffset(0, #LOGLINES * 16 + 8)
    logPage.CanvasPosition = Vector2.new(0, math.max(0, #LOGLINES * 16 - 160))
end

getgenv().KaitunLog = klog

local exportBtn = button(logPage, "Xuất log ra file", UDim2.new(1, -8, 0, 24), UDim2.fromOffset(4, 0), C.accent)
exportBtn.ZIndex = 5
exportBtn.MouseButton1Click:Connect(function()
    if type(writefile) ~= "function" then
        StatusLabel.Text = " Status : Executor không hỗ trợ writefile"
        return
    end
    local ok = pcall(function()
        writefile("KaitunLog.txt", table.concat(LOGLINES, "\n"))
    end)
    StatusLabel.Text = ok and " Status : Đã xuất KaitunLog.txt" or " Status : Xuất log lỗi"
    klog(ok and "đã xuất KaitunLog.txt" or "xuất log lỗi")
end)
klog("menu khởi động")

