-- cac ham dong bo hien thi theo Configs (de UI khong bi cu khi
-- script khac sua getgenv().Configs truc tiep)
local SYNCS = {}

local function toggleRow(parent, text, get, set, order)
    local row = new("Frame", {
        Size = UDim2.new(1, 0, 0, 34),
        BackgroundColor3 = C.row,
        BorderSizePixel = 0,
        LayoutOrder = order,
    }, parent)
    corner(row, 6)
    row.__labelText = text
    label(row, text, UDim2.new(1, -60, 1, 0), C.text, UDim2.fromOffset(12, 0))

    local pill = new("Frame", {
        Size = UDim2.fromOffset(38, 18),
        Position = UDim2.new(1, -50, 0.5, -9),
        BackgroundColor3 = get() and C.accent2 or C.off,
        BorderSizePixel = 0,
    }, row)
    corner(pill, 9)

    local knob = new("Frame", {
        Size = UDim2.fromOffset(14, 14),
        Position = get() and UDim2.fromOffset(21, 2) or UDim2.fromOffset(3, 2),
        BackgroundColor3 = C.text,
        BorderSizePixel = 0,
    }, pill)
    corner(knob, 7)

    local hit = new("TextButton", {
        Size = UDim2.fromScale(1, 1),
        BackgroundTransparency = 1,
        Text = "",
    }, row)

    local shown = get() and true or false
    SYNCS[#SYNCS + 1] = function()
        local v = get() and true or false
        if v == shown then return end
        shown = v
        pill.BackgroundColor3 = v and C.accent2 or C.off
        knob.Position = v and UDim2.fromOffset(21, 2) or UDim2.fromOffset(3, 2)
    end

    hit.MouseButton1Click:Connect(function()
        local v = not get()
        set(v)
        TweenService:Create(pill, TweenInfo.new(0.15), {
            BackgroundColor3 = v and C.accent2 or C.off,
        }):Play()
        TweenService:Create(knob, TweenInfo.new(0.15), {
            Position = v and UDim2.fromOffset(21, 2) or UDim2.fromOffset(3, 2),
        }):Play()
    end)
    return row
end

local function sliderRow(parent, text, minv, maxv, get, set, order)
    local row = new("Frame", {
        Size = UDim2.new(1, 0, 0, 46),
        BackgroundColor3 = C.row,
        BorderSizePixel = 0,
        LayoutOrder = order,
    }, parent)
    corner(row, 6)
    local lb = label(row, text, UDim2.new(1, -70, 0, 20), C.text, UDim2.fromOffset(12, 4))
    local val = label(row, tostring(get()), UDim2.fromOffset(60, 20), C.accent2, UDim2.new(1, -68, 0, 4))
    val.TextXAlignment = Enum.TextXAlignment.Right

    local track = new("Frame", {
        Size = UDim2.new(1, -24, 0, 5),
        Position = UDim2.new(0, 12, 1, -14),
        BackgroundColor3 = C.off,
        BorderSizePixel = 0,
    }, row)
    corner(track, 3)

    local fill = new("Frame", {
        Size = UDim2.fromScale((get() - minv) / (maxv - minv), 1),
        BackgroundColor3 = C.accent,
        BorderSizePixel = 0,
    }, track)
    corner(fill, 3)

    local hit = new("TextButton", {
        Size = UDim2.new(1, 0, 0, 24),
        Position = UDim2.new(0, 0, 0, 16),
        BackgroundTransparency = 1,
        Text = "",
    }, row)

    local dragging = false
    local function apply(x)
        local rel = math.clamp((x - track.AbsolutePosition.X) / track.AbsoluteSize.X, 0, 1)
        local v = math.floor(minv + rel * (maxv - minv) + 0.5)
        set(v)
        val.Text = tostring(v)
        fill.Size = UDim2.fromScale(rel, 1)
    end
    local shownV = get()
    SYNCS[#SYNCS + 1] = function()
        local v = get()
        if v == shownV then return end
        shownV = v
        val.Text = tostring(v)
        fill.Size = UDim2.fromScale(math.clamp((v - minv) / (maxv - minv), 0, 1), 1)
    end

    hit.MouseButton1Down:Connect(function() if current() then dragging = true end end)
    svcConnect(UserInputService.InputEnded, function(i)
        if current() and i.UserInputType == Enum.UserInputType.MouseButton1 then
            dragging = false
        end
    end)
    svcConnect(UserInputService.InputChanged, function(i)
        if not current() then return end
        if dragging and i.UserInputType == Enum.UserInputType.MouseMovement then
            apply(i.Position.X)
        end
    end)
    return row
end

local function textRow(parent, text, placeholder, get, set, order)
    local row = new("Frame", {
        Size = UDim2.new(1, 0, 0, 52),
        BackgroundColor3 = C.row,
        BorderSizePixel = 0,
        LayoutOrder = order,
    }, parent)
    corner(row, 6)
