local function bulkButtons(page, names, set, commit, tag)
    local row = new("Frame", {
        Size = UDim2.new(1, 0, 0, 30),
        BackgroundTransparency = 1,
        LayoutOrder = -2,
    }, page)
    local function mk(labelText, value, colour)
        local b = button(row, labelText, UDim2.new(0.5, -4, 1, 0),
            UDim2.fromScale(value and 0.5 or 0, 0), colour)
        b.TextSize = 11
        b.MouseButton1Click:Connect(function()
            for _, n in ipairs(names) do set[n] = value end
            commit()
            klog(tag .. ": " .. labelText .. " (" .. #names .. " mục)")
            local ui = getgenv().KaitunUI
            if ui and ui.StatusLabel then
                ui.StatusLabel.Text = " Status : " .. tag .. " — " .. labelText
            end
        end)
        return b
    end
    mk("Tắt tất cả", false, C.row)
    mk("Bật tất cả", true, C.accent)
    return row
end

local function addSearch(page)
    local box = new("TextBox", {
        Size = UDim2.new(1, 0, 0, 28),
        BackgroundColor3 = C.bg,
        BorderSizePixel = 0,
        Font = Enum.Font.Gotham,
        TextSize = 12,
        TextColor3 = C.text,
        PlaceholderText = "tìm theo tên gốc (VD: Katana)",
        PlaceholderColor3 = C.sub,
        Text = "",
        ClearTextOnFocus = false,
        TextXAlignment = Enum.TextXAlignment.Left,
        LayoutOrder = -1,
    }, page)
    corner(box, 6)
    new("UIPadding", { PaddingLeft = UDim.new(0, 8) }, box)
    return box
end

local function applyFilter(box, rows)
    local q = string.lower(box.Text)
    for _, r in ipairs(rows) do
        if q == "" then
            r.Visible = true
        else
            r.Visible = string.find(string.lower(r.__labelText or ""), q, 1, true) ~= nil
        end
    end
end

