-- ---------- Teleport page (toạ độ thật lấy từ hub) ----------
local DESTS = {
    { name = "Castle",  x = -5027.03,  y = 326.79, z = -3206.70 },
    { name = "Hydra",   x = 5650.95,   y = 1025.57, z = -350.38 },
    { name = "Mansion", x = -12463.60, y = 386.62,  z = -7566.08 },
    { name = "Tiki",    x = -16800.35, y = 60.26,   z = 290.22 },
}

local yOff = 0

local function doTeleport(x, y, z)
    local ok, err = pcall(function()
        local lp = Players.LocalPlayer
        local ch = lp.Character
        if not ch then error("chưa có nhân vật") end
        local root = ch:FindFirstChild("HumanoidRootPart")
        if not root then error("không thấy HumanoidRootPart") end
        root.CFrame = CFrame.new(x, y + (yOff or 0), z)
    end)
    if ok then
        StatusLabel.Text = string.format(" Status : Đã teleport tới %d, %d, %d",
            math.floor(x), math.floor(y), math.floor(z))
        klog(string.format("teleport %d,%d,%d OK", math.floor(x), math.floor(y), math.floor(z)))
    else
        StatusLabel.Text = " Status : Teleport lỗi"
        klog("teleport lỗi: " .. tostring(err))
    end
    return ok
end

for _, d in ipairs(DESTS) do
    local b = button(pages.TP, d.name, UDim2.new(1, 0, 0, 34), nil, C.row)
    b.LayoutOrder = nextOrder()
    b.MouseButton1Click:Connect(function() doTeleport(d.x, d.y, d.z) end)
end

