local pHPRow,    pHP    = infoRow(pages.Player, "Máu", "-", nextOrder())
local pPosRow,   pPos   = infoRow(pages.Player, "Vị trí", "-", nextOrder())
local pPlaceRow, pPlace = infoRow(pages.Player, "PlaceId", "-", nextOrder())
local pGameRow,  pGame  = infoRow(pages.Player, "GameId", "-", nextOrder())
local pExecRow,  pExec  = infoRow(pages.Player, "Executor", "-", nextOrder())

-- so an toan: NaN hoac vo cung thi hien "?" thay vi -9223372036854775808
local function safeNum(v, fmt)
    if type(v) ~= "number" or v ~= v or v == math.huge or v == -math.huge
       or v > 1e15 or v < -1e15 then
        return "?"
    end
    return string.format(fmt, math.floor(v))
end

local function updPlayer()
    local ok, lp = pcall(function() return Players.LocalPlayer end)
    if ok and lp then
        pName.Text = tostring(lp.Name or "?")
        local ok2, ch = pcall(function() return lp.Character end)
        if ok2 and ch then
            local ok3, hum = pcall(function() return ch:FindFirstChildOfClass("Humanoid") end)
            if ok3 and hum then
                pName.Text = tostring(lp.Name) .. (hum.Health <= 0 and "  (đã chết)" or "")
                pHP.Text = safeNum(hum.Health, "%d") .. " / " .. safeNum(hum.MaxHealth, "%d")
            end
            local ok4, root = pcall(function() return ch:FindFirstChild("HumanoidRootPart") end)
            if ok4 and root then
                local ok5, p = pcall(function() return root.Position end)
                if ok5 and p then
                    pPos.Text = safeNum(p.X, "%d") .. ", " .. safeNum(p.Y, "%d")
                        .. ", " .. safeNum(p.Z, "%d")
                end
            end
        end
    end
    local ok6, pid = pcall(function() return game.PlaceId end)
    if ok6 then pPlace.Text = tostring(pid) end
    local ok7, gid = pcall(function() return game.GameId end)
    if ok7 then pGame.Text = tostring(gid) end
    local ex = getgenv().KaitunExecutor
    if ex then pExec.Text = tostring(ex) end
end

pcall(function()
    local ok, name = pcall(function() return identifyexecutor() end)
    if ok and name then
        getgenv().KaitunExecutor = name
    elseif typeof(identifyexecutor) == "function" then
        getgenv().KaitunExecutor = tostring(identifyexecutor())
    end
end)

