-- ---------- persistence + reload ----------

local function saveConfig()
    if type(writefile) ~= "function" then return false end
    local ok = pcall(function()
        local function quote(s)
            -- escape MỌI ký tự điều khiển, không chỉ \n: NUL và CR cũng làm hỏng file
            local out = tostring(s):gsub('[%z\1-\31\\"]', function(c)
                if c == '\\' then return '\\\\' end
                if c == '"' then return '\\"' end
                if c == '\n' then return '\\n' end
                if c == '\r' then return '\\r' end
                if c == '\t' then return '\\t' end
                return string.format('\\%d', string.byte(c))
            end)
            return '"' .. out .. '"'
        end
        local ser
        ser = function(v, ind, seen)
            ind = ind or ""
            local t = type(v)
            if t == "table" then
                seen = seen or {}
                if seen[v] then return '"<cycle>"' end
                seen[v] = true
                local isArr = true
                local n = 0
                for _ in pairs(v) do n = n + 1 end
                for k in pairs(v) do if type(k) ~= "number" then isArr = false break end end
                local out = {"{"}
                if isArr and n > 0 then
                    for i = 1, n do out[#out+1] = ser(v[i], ind.."  ", seen).."," end
                else
                    local keys = {}
                    for k in pairs(v) do keys[#keys+1] = k end
                    table.sort(keys, function(a,b) return tostring(a) < tostring(b) end)
                    for _, k in ipairs(keys) do
                        out[#out+1] = ind..'  ['..quote(tostring(k))..']='..ser(v[k], ind.."  ", seen)..","
                    end
                end
                out[#out+1] = ind.."}"
                seen[v] = nil
                return table.concat(out, "\n")
            elseif t == "string" then
                return quote(v)
            elseif t == "number" or t == "boolean" then
                return tostring(v)
            end
            return "nil"
        end
        writefile(SAVEFILE, ser(Configs))
    end)
    return ok
end



