local copyBtn = button(pages.Settings, "Copy config", UDim2.new(1, 0, 0, 32), nil, C.row)
copyBtn.LayoutOrder = nextOrder()
copyBtn.MouseButton1Click:Connect(function()
    if type(setclipboard) ~= "function" then
        StatusLabel.Text = " Status : Executor không hỗ trợ clipboard"
        klog("setclipboard không khả dụng")
        return
    end
    local parts = {}
    for k, v in pairs(Configs) do
        local t = type(v)
        if t == "table" then
            local sub = {}
            for k2, v2 in pairs(v) do
                sub[#sub + 1] = string.format('        [%q] = %s;',
                    tostring(k2), type(v2) == "string" and string.format("%q", v2) or tostring(v2))
            end
            parts[#parts + 1] = string.format('    [%q] = {\n%s\n    };', k, table.concat(sub, "\n"))
        else
            parts[#parts + 1] = string.format('    [%q] = %s;', k,
                t == "string" and string.format("%q", v) or tostring(v))
        end
    end
    local out = "getgenv().Configs = {\n" .. table.concat(parts, "\n") .. "\n};"
    pcall(setclipboard, out)
    StatusLabel.Text = " Status : Đã copy config vào clipboard"
    klog("copy config (" .. #out .. " B)")
end)

