-- ---------- interaction ----------
local function makeDraggable(frame, handle)
    local dragging, start, startPos = false, nil, nil
    handle.InputBegan:Connect(function(i)
        if not current() then return end
        if i.UserInputType == Enum.UserInputType.MouseButton1 then
            dragging = true
            start = i.Position
            startPos = frame.Position
        end
    end)
    svcConnect(UserInputService.InputEnded, function(i)
        if not current() then return end
        if i.UserInputType == Enum.UserInputType.MouseButton1 and dragging then
            dragging = false
            local p = frame.Position
            Configs["WindowGeom"] = Configs["WindowGeom"] or {}
            Configs["WindowGeom"].PX = p.X.Offset
            Configs["WindowGeom"].PY = p.Y.Offset
            Configs["WindowGeom"].W = frame.Size.X.Offset
            Configs["WindowGeom"].H = frame.Size.Y.Offset
        end
    end)
    svcConnect(UserInputService.InputChanged, function(i)
        if not current() then return end
        if dragging and i.UserInputType == Enum.UserInputType.MouseMovement then
            local d = i.Position - start
            frame.Position = UDim2.new(
                startPos.X.Scale, startPos.X.Offset + d.X,
                startPos.Y.Scale, startPos.Y.Offset + d.Y)
        end
    end)
end
makeDraggable(win, bar)

