    Name = "Resizer",
    Size = UDim2.new(0, 18, 0, 18),
    Position = UDim2.new(1, -18, 1, -18),
    BackgroundTransparency = 1,
    Text = "◢",
    TextColor3 = C.sub,
    TextSize = 13,
    AutoButtonColor = false,
    ZIndex = 10,
}, win)

do
    local resizing, rStart, rBase = false, nil, nil
    resizer.InputBegan:Connect(function(i)
        if current() and i.UserInputType == Enum.UserInputType.MouseButton1 then
            resizing = true
            rStart = i.Position
            rBase = { w = win.Size.X.Offset, h = win.Size.Y.Offset }
        end
    end)
    svcConnect(UserInputService.InputEnded, function(i)
        if i.UserInputType == Enum.UserInputType.MouseButton1 and resizing then
            resizing = false
            Configs["WindowGeom"] = Configs["WindowGeom"] or {}
            Configs["WindowGeom"].W = win.Size.X.Offset
            Configs["WindowGeom"].H = win.Size.Y.Offset
        end
    end)
    svcConnect(UserInputService.InputChanged, function(i)
        if current() and resizing and i.UserInputType == Enum.UserInputType.MouseMovement and rBase then
            local d = i.Position - rStart
            local nw = math.clamp(rBase.w + d.X, 320, 1200)
            local nh = math.clamp(rBase.h + d.Y, 260, 900)
            win.Size = UDim2.fromOffset(nw, nh)
        end
    end)
end


-- ---------- keybind ----------
local TOGGLE_KEY = Enum.KeyCode.RightControl

svcConnect(UserInputService.InputBegan, function(input, processed)
    if not current() then return end
    if processed then return end
    if input.KeyCode == TOGGLE_KEY then
        gui.Enabled = not gui.Enabled
        getgenv().KaitunMenuOpen = gui.Enabled
        if gui.Enabled then
            klog("menu mở (RightCtrl)")
        end
    end
end)

closeBtn.MouseButton1Click:Connect(function()
    gui.Enabled = false
    getgenv().KaitunMenuOpen = false
end)

local minimized = false
minBtn.MouseButton1Click:Connect(function()
    minimized = not minimized
    for _, ch in ipairs(win:GetChildren()) do
        if ch ~= bar then ch.Visible = not minimized end
    end
    win.Size = minimized and UDim2.fromOffset(W, 38) or UDim2.fromOffset(W, H)
    minBtn.Text = minimized and "+" or "—"
end)

-- khôi phục tab đã chọn lần trước (nếu hợp lệ)
local startTab = Configs["LastTab"]
if type(startTab) ~= "string" or not pages[startTab] then startTab = "Quest" end
showTab(startTab)
refreshCounts()

-- đẩy cờ đã lưu vào getgenv() để engine đọc được ngay
-- Đẩy cờ đã lưu vào getgenv() cho engine đọc.
-- CHỈ nhận giá trị dữ liệu (bool/số/chuỗi) và KHÔNG đụng vào namespace "Kaitun"
-- của chính menu — nếu không, một file config lạ có thể ghi đè KaitunStop /
-- KaitunReload / KaitunUI bằng hàm của nó và phá hoặc chiếm quyền điều khiển.
-- Chỉ chặn đúng những tên là API của chính menu. KHÔNG chặn cả namespace
-- "Kaitun": KaitunSpeed / KaitunWalkSpeed là cờ hợp lệ của người dùng.
local RESERVED = {
    KaitunUI = true, KaitunStop = true, KaitunReload = true, KaitunLog = true,
    KaitunCounts = true, KaitunMenuOpen = true, KaitunGeneration = true,
    KaitunExecutor = true, KaitunEngineName = true, KaitunEngineChoice = true,
    KaitunMenuConns = true, KaitunInventoryCache = true,
}
for fk, fv in pairs(Configs.Features or {}) do
    local tv = type(fv)
    local is_data = (tv == "boolean" or tv == "number" or tv == "string")
    if is_data and not RESERVED[fk] then
        local cur = getgenv()[fk]
        if type(cur) ~= "function" then getgenv()[fk] = fv end
    end
end

-- status updater
task.spawn(function()
    local t0 = tick()
    while gui.Parent do
        local ok, fps = pcall(function() return math.floor(1 / RunService.RenderStepped:Wait()) end)
        if ok and fps then
            refreshTitle()
            pcall(updPlayer)
            for _, sync in ipairs(SYNCS) do pcall(sync) end
            do
                -- kaitun ghi KaitunInventoryCache, bloxfruits ghi RealKidInventoryCache
                local c = getgenv().KaitunInventoryCache or getgenv().RealKidInventoryCache
                if type(c) == "table" then
                    local n = 0
                    if type(c.ByName) == "table" then
                        for _ in pairs(c.ByName) do n = n + 1 end
                    elseif type(c.Items) == "table" then
                        for _ in pairs(c.Items) do n = n + 1 end
                    else
                        for _ in pairs(c) do n = n + 1 end
                    end
                    local txt = n .. " vật phẩm"
                    if type(c.Materials) == "table" then
                        local m = 0
                        for _ in pairs(c.Materials) do m = m + 1 end
                        txt = txt .. " • " .. m .. " nguyên liệu"
                    end
                    cacheVal.Text = txt
                else
                    cacheVal.Text = "chưa có"
                end
                engineVal.Text = tostring(getgenv().KaitunEngineName or "-")
            end
            DebugLabel.Text = string.format("fps %d   •   up %d s   •   configs %d keys",
                fps, math.floor(tick() - t0), (function()
                    local n = 0
                    for _ in pairs(Configs) do n = n + 1 end
                    return n
                end)())
        end
    end
end)

return gui

end)()

local __ui = getgenv().KaitunUI
if __ui and __ui.StatusLabel then
    __ui.StatusLabel.Text = " Status : " .. __ENGINE .. " đang khởi động..."
end
__start_engine()
return getgenv().KaitunUI
